package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpServer;
import java.math.BigDecimal;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

class HttpPaymentGatewayTest {

    private HttpServer provider;
    private HttpPaymentGateway gateway;
    private final AtomicReference<String> method = new AtomicReference<>();
    private final AtomicReference<String> path = new AtomicReference<>();
    private final AtomicReference<String> contentType = new AtomicReference<>();
    private final AtomicReference<String> body = new AtomicReference<>();
    private volatile int status;
    private volatile String responseBody;

    @BeforeEach
    void startProvider() throws Exception {
        provider = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), 0), 0);
        provider.createContext("/", exchange -> {
            method.set(exchange.getRequestMethod());
            path.set(exchange.getRequestURI().getPath());
            contentType.set(exchange.getRequestHeaders().getFirst("Content-Type"));
            body.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
            var payload = responseBody.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, payload.length == 0 ? -1 : payload.length);
            if (payload.length > 0) exchange.getResponseBody().write(payload);
            exchange.close();
        });
        provider.start();
        gateway = new HttpPaymentGateway(RestClient.builder()
                .baseUrl("http://127.0.0.1:" + provider.getAddress().getPort())
                .build());
    }

    @AfterEach
    void stopProvider() {
        provider.stop(0);
    }

    @Test
    void the_authorization_request_is_posted_as_json_with_reference_amount_and_currency() throws Exception {
        reply(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        assertThat(method.get()).isEqualTo("POST");
        assertThat(path.get()).isEqualTo("/v1/authorizations");
        assertThat(contentType.get()).startsWith("application/json");
        JsonNode sent = new ObjectMapper().readTree(body.get());
        assertThat(sent.fieldNames()).toIterable().containsExactlyInAnyOrder("reference", "amount", "currency");
        assertThat(sent.get("reference").asText()).isEqualTo("ORD-7");
        assertThat(sent.get("amount").decimalValue()).isEqualByComparingTo("12.50");
        assertThat(sent.get("currency").asText()).isEqualTo("EUR");
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        reply(200, "{\"status\":\"approved\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        reply(200, "{\"status\":\"declined\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void unknown_fields_in_the_answer_are_ignored() {
        reply(200, "{\"status\":\"approved\",\"id\":\"auth-1\",\"risk\":{\"score\":3}}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_refusal_with_402_is_a_decline() {
        reply(402, "{\"error\":\"card_refused\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_refusal_with_402_and_no_body_is_a_decline() {
        reply(402, "");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unrecognised_status_is_never_treated_as_approved() {
        reply(200, "{\"status\":\"pending\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_approved() {
        reply(200, "{\"decision\":\"approved\"}");

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_provider_rejecting_our_request_with_400_is_reported_as_a_failure() {
        reply(400, "{\"error\":\"invalid_currency\"}");

        assertThatThrownBy(this::authorize)
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_with_503_is_reported_as_a_failure() {
        reply(503, "");

        assertThatThrownBy(this::authorize)
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }

    private void reply(int status, String responseBody) {
        this.status = status;
        this.responseBody = responseBody;
    }

    private AuthorizationOutcome authorize() {
        return gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "EUR"));
    }
}
